<div class="page-actions"><div><p class="muted">Admin dan Petugas Gudang dapat membuat, memesan, dan menerima Purchase Order.</p></div><a class="btn btn-primary" href="?page=purchase&amp;action=create">+ Purchase Order</a></div>
<div class="card filter-card"><form method="get" class="filter-grid"><input type="hidden" name="page" value="purchase"><label class="sr-only" for="purchase-search">Cari PO atau supplier</label><input id="purchase-search" name="search" value="<?=e($filters['search'])?>" placeholder="Cari nomor PO atau supplier"><label class="sr-only" for="purchase-status">Status PO</label><select id="purchase-status" name="status"><option value="">Semua status</option><?php foreach(['Draft','Ordered','PartiallyReceived','Received','Cancelled'] as $status):?><option value="<?=e($status)?>" <?=$filters['status']===$status?'selected':''?>><?=e($status)?></option><?php endforeach;?></select><label class="sr-only" for="purchase-sort">Urutan PO</label><select id="purchase-sort" name="sort"><option value="date_desc" <?=$filters['sort']==='date_desc'?'selected':''?>>Tanggal terbaru</option><option value="date_asc" <?=$filters['sort']==='date_asc'?'selected':''?>>Tanggal terlama</option></select><button class="btn btn-primary">Filter</button><a class="btn" href="?page=purchase">Reset</a></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Nomor PO</th><th>Tanggal</th><th>Supplier</th><th>Gudang</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($result['items'] as $order):?><tr><td><a class="link" href="?page=purchase&amp;action=view&amp;id=<?=$order['id']?>"><?=e($order['po_number'])?></a></td><td><?=e($order['po_date'])?></td><td><?=e($order['supplier_name'])?></td><td><?=e($order['warehouse_name'])?></td><td>Rp <?=number_format((float)$order['total_amount'],0,',','.')?></td><td><span class="badge status-<?=strtolower((string)$order['status'])?>"><?=e($order['status'])?></span></td><td><?php if(in_array(($currentUser['role']??''),['Admin','WarehouseStaff'],true) && $order['status'] === 'Draft'):?><form class="inline-form" method="post" action="?page=purchase&amp;action=status&amp;id=<?=$order['id']?>"><?=$csrfField?><input type="hidden" name="status" value="Ordered"><button class="btn btn-sm">Pesan</button></form><form class="inline-form" method="post" action="?page=purchase&amp;action=status&amp;id=<?=$order['id']?>"><?=$csrfField?><input type="hidden" name="status" value="Cancelled"><button class="btn btn-sm">Batalkan</button></form><?php elseif(in_array(($currentUser['role']??''),['Admin','WarehouseStaff'],true) && in_array($order['status'],['Ordered','PartiallyReceived'],true)):?><a class="btn btn-sm" href="?page=purchase&amp;action=view&amp;id=<?=$order['id']?>">Terima barang</a><?php else:?>-<?php endif;?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="7" class="empty">Tidak ada Purchase Order yang cocok dengan filter.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($result,['page'=>'purchase','search'=>$filters['search'],'status'=>$filters['status'],'sort'=>$filters['sort']])?></div>
